for layer, he, ru, focus, cloze in CARDS:
    he, focus, cloze = N(he), N(focus), N(cloze)
    assert cloze in he, (cloze, he)
    out.append({"chapter": "shabbat", "layer": layer, "he": he, "ru": ru, "focus_word": focus, "cloze_token": cloze})
p = os.path.join(os.path.dirname(os.path.abspath(__file__)), "shabbat_cards.json")
json.dump(out, open(p, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
print(len(out), "карточек →", p)
